content:
{
  "findings": [
    {
      "check_id": "CKV_AWS_23",
      "title": "Security group allows ingress from 0.0.0.0/0",
      "resource": "aws_security_group.vault",
      "severity": "HIGH",
      "explanation": "Allowing ingress from 0.0.0.0/0 exposes the resource to the entire internet, which increases the risk of unauthorized access. This is particularly risky for sensitive services like Vault."
    }
  ],
  "patched_code": "resource "aws_security_group" "vault" {
  name        = "vault"
  description = "Ingress for Vault"
  vpc_id      = aws_vpc.my_vpc.id
  dynamic "ingress" {
    iterator = port
    for_each = var.ingress_ports
    content {
      from_port   = port.value
      to_port     = port.value
      protocol    = "tcp"
      cidr_blocks = var.allowed_cidr_blocks
    }
  }
}

variable "allowed_cidr_blocks" {
  description = "List of allowed CIDR blocks for ingress."
  type        = list(string)
  default     = []
}",
  "fix_summary": "Replaced the hardcoded '0.0.0.0/0' CIDR block with a variable 'allowed_cidr_blocks' to allow specifying more restrictive ingress rules."
}
